    _observe: function(cfg) {
        rh.movimentacao.possession.benefit.Window.superclass._observe.call(this, cfg);

        if (this.oId){
            grid = this.getPanelSuspension()
            grid.enable()
            grid.setParam("benefit_movement", this.oId);
            grid.setFilterProperty("benefit_movement__id", this.oId);
        } else{
            this.getPanelSuspension().disable()
        }

        var values = this.getParams();
        if(values != undefined && values.servidor != undefined){
            this.getPossessionField().setPreFilter([
                {
                    property: 'servidor__id',
                    value: values.servidor,
                    stage: 0,
                }
            ]);

            if(this.getEmployeeField().preFilter == undefined)
                this.getEmployeeField().setPreFilter([
                    {
                        property: 'id',
                        value: values.servidor,
                        stage: 0,
                    }
                ]);

            this.getReativatedField().setPreFilter([
                {
                    property: 'servidor__id',
                    value: values.servidor,
                    stage: 0,
                }
            ]);
        }
        // this._suspensionGrid.setFilterProperty('benefit_movement__pk', this.oId, 1000)
    },

